*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --cream: #f7f4ef;
    --blush: #e8d5c4;
    --rose: #c9a99a;
    --dusty: #b08a80;
    --dark: #2a1f1a;
    --gold: #c9a96e;
    --smoke: #9a9090;
  }

  html, body { width: 100%; min-height: 100vh; }

  body {
    background: var(--cream);
    font-family: 'Jost', sans-serif;
    font-weight: 300;
    color: var(--dark);
    cursor: none;
    overflow-x: hidden;
  }

  /* ── CUSTOM CURSOR ── */
  #cursor-dot {
    width: 6px; height: 6px;
    background: var(--dark);
    border-radius: 50%;
    position: fixed; top: 0; left: 0;
    pointer-events: none;
    z-index: 9999;
    transform: translate(-50%, -50%);
    transition: transform 0.08s ease, background 0.3s;
  }
  #cursor-ring {
    width: 32px; height: 32px;
    border: 1px solid var(--dark);
    border-radius: 50%;
    position: fixed; top: 0; left: 0;
    pointer-events: none;
    z-index: 9998;
    transform: translate(-50%, -50%);
    transition: width 0.4s cubic-bezier(.23,1,.32,1),
                height 0.4s cubic-bezier(.23,1,.32,1),
                border-color 0.3s,
                background 0.3s;
  }
  body.cursor-hover #cursor-ring {
    width: 56px; height: 56px;
    border-color: var(--gold);
    background: rgba(201,169,110,0.08);
  }
  body.cursor-hover #cursor-dot { background: var(--gold); }

  body.cursor-text #cursor-ring {
    width: 80px; height: 80px;
    background: var(--dark);
    border-color: var(--dark);
  }
  body.cursor-text #cursor-dot { background: var(--cream); }

  /* ── NAV TABS ── */
  #nav-tabs {
    position: fixed; top: 0; left: 0; right: 0;
    z-index: 200;
    display: flex; align-items: center; justify-content: center;
    padding: 20px;
    gap: 2px;
    background: rgba(247,244,239,0.85);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid rgba(201,169,110,0.2);
  }
  .tab-btn {
    font-family: 'Jost', sans-serif;
    font-weight: 200;
    font-size: 10px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--smoke);
    background: none; border: none;
    padding: 8px 16px;
    cursor: none;
    position: relative;
    transition: color 0.3s;
  }
  .tab-btn::after {
    content: '';
    position: absolute; bottom: 4px; left: 16px; right: 16px;
    height: 1px; background: var(--gold);
    transform: scaleX(0); transition: transform 0.4s cubic-bezier(.23,1,.32,1);
  }
  .tab-btn:hover, .tab-btn.active { color: var(--dark); }
  .tab-btn.active::after { transform: scaleX(1); }

  /* ── SECTIONS ── */
  .section {
    display: none; min-height: 100vh;
    padding: 100px 40px 60px;
  }
  .section.active { display: flex; flex-direction: column; align-items: center; }

  .section-title {
    font-family: 'Cormorant Garamond', serif;
    font-weight: 300;
    font-size: clamp(28px, 4vw, 42px);
