  }

  /* ════════════════════════════════
     SECTION 1 — BURGER MENUS
  ════════════════════════════════ */
  .burger-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 40px;
    width: 100%; max-width: 900px;
  }
  .burger-card {
    background: white;
    border: 1px solid rgba(201,169,110,0.15);
    padding: 40px 32px;
    display: flex; flex-direction: column; align-items: center; gap: 20px;
    position: relative;
    overflow: hidden;
  }
  .burger-card::before {
    content: attr(data-label);
    position: absolute; top: 16px; right: 16px;
    font-size: 8px; letter-spacing: 0.2em; text-transform: uppercase;
    color: var(--smoke);
  }
  .burger-label {
    font-size: 9px; letter-spacing: 0.2em; text-transform: uppercase;
    color: var(--smoke);
  }

  /* Burger 1 — Classic Lines */
  .burger-1 { width: 36px; height: 24px; display: flex; flex-direction: column; justify-content: space-between; cursor: none; }
  .burger-1 span {
    display: block; height: 1px; background: var(--dark);
    transition: all 0.5s cubic-bezier(.23,1,.32,1);
    transform-origin: center;
  }
  .burger-1.open span:nth-child(1) { transform: translateY(11.5px) rotate(45deg); }
  .burger-1.open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
  .burger-1.open span:nth-child(3) { transform: translateY(-11.5px) rotate(-45deg); }

  /* Burger 2 — Stagger Slide */
  .burger-2 { width: 36px; height: 22px; display: flex; flex-direction: column; justify-content: space-between; cursor: none; }
  .burger-2 span {
    display: block; height: 1px; background: var(--dark);
    transition: all 0.4s cubic-bezier(.23,1,.32,1);
  }
  .burger-2 span:nth-child(1) { width: 100%; }
  .burger-2 span:nth-child(2) { width: 70%; margin-left: auto; }
  .burger-2 span:nth-child(3) { width: 40%; margin-left: auto; }
  .burger-2.open span:nth-child(1) { transform: translateY(10px) rotate(45deg); width: 100%; }
  .burger-2.open span:nth-child(2) { opacity: 0; width: 0; }
  .burger-2.open span:nth-child(3) { transform: translateY(-10px) rotate(-45deg); width: 100%; }

  /* Burger 3 — Dot Matrix */
  .burger-3 {
    width: 30px; height: 30px;
    display: grid; grid-template-columns: repeat(3,8px);
    grid-template-rows: repeat(3,8px);
    gap: 3px; cursor: none;
  }
  .burger-3 span {
    display: block; border-radius: 50%;
    background: var(--dark);
    transition: all 0.5s cubic-bezier(.23,1,.32,1);
  }
  .burger-3.open span { background: var(--gold); }
  .burger-3.open span:nth-child(1) { transform: translate(19px,19px); }
  .burger-3.open span:nth-child(3) { transform: translate(-19px,19px); }
  .burger-3.open span:nth-child(7) { transform: translate(19px,-19px); }
  .burger-3.open span:nth-child(9) { transform: translate(-19px,-19px); }
  .burger-3.open span:nth-child(5) { transform: scale(1.5); }

  /* Burger 4 — Morph Circle */
  .burger-4 {
    width: 40px; height: 40px;
    border-radius: 50%;
    border: 1px solid var(--dark);
    display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 5px;
    cursor: none;
    transition: all 0.5s cubic-bezier(.23,1,.32,1);
  }
  .burger-4 span { display: block; width: 16px; height: 1px; background: var(--dark); transition: all 0.5s cubic-bezier(.23,1,.32,1); }
  .burger-4.open { background: var(--dark); }
  .burger-4.open span { background: var(--cream); }
  .burger-4.open span:nth-child(1) { transform: translateY(6px) rotate(45deg); }
  .burger-4.open span:nth-child(2) { opacity: 0; }
  .burger-4.open span:nth-child(3) { transform: translateY(-6px) rotate(-45deg); }

  /* ── DROPDOWN OVERLAY ── */
  #menu-overlay {
    position: fixed; inset: 0; z-index: 500;
    background: var(--dark);
    clip-path: circle(0% at calc(100% - 60px) 60px);
    transition: clip-path 0.8s cubic-bezier(.23,1,.32,1);
    display: flex; align-items: center; justify-content: center;
    pointer-events: none;
  }
  #menu-overlay.open {
    clip-path: circle(150% at calc(100% - 60px) 60px);
    pointer-events: all;
  }
  .overlay-inner {
    display: grid; grid-template-columns: 1fr 1fr;
    gap: 0; max-width: 800px; width: 100%;
    padding: 60px;
    opacity: 0; transform: translateY(30px);
    transition: all 0.5s 0.3s cubic-bezier(.23,1,.32,1);
  }
  #menu-overlay.open .overlay-inner { opacity: 1; transform: none; }

  .menu-category {
    padding: 30px;
    border-left: 1px solid rgba(247,244,239,0.1);
  }
  .menu-category:nth-child(1), .menu-category:nth-child(2) {
    border-top: none;
  }
  .cat-title {
    font-family: 'Cormorant Garamond', serif;
    font-size: 11px;
    letter-spacing: 0.25em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 20px;
    display: flex; align-items: center; gap: 10px;
  }
  .cat-title::before { content: ''; display: block; width: 20px; height: 1px; background: var(--gold); }
  .menu-link {
    display: block;
    font-family: 'Cormorant Garamond', serif;
    font-size: 24px;
    font-weight: 300;
    color: rgba(247,244,239,0.6);
    text-decoration: none;
    padding: 6px 0;
    cursor: none;
    transition: all 0.3s;
    position: relative;
    letter-spacing: 0.02em;
  }
  .menu-link::after {
    content: '→';
    position: absolute; right: 0;
    opacity: 0; transform: translateX(-8px);
    transition: all 0.3s;
    font-size: 14px;
    color: var(--gold);
  }
  .menu-link:hover { color: var(--cream); padding-left: 8px; }
  .menu-link:hover::after { opacity: 1; transform: none; }

  .overlay-close {
    position: absolute; top: 30px; right: 30px;
    width: 40px; height: 40px;
    display: flex; align-items: center; justify-content: center;
    cursor: none;
    color: var(--cream);
    font-size: 20px;
    border: 1px solid rgba(247,244,239,0.2);
