  /* ════════════════════════════════
     SECTION 2 — CTAs
  ════════════════════════════════ */
  .cta-grid {
    display: flex; flex-wrap: wrap; gap: 30px;
    justify-content: center; max-width: 900px;
  }

  /* CTA 1 — Underline Reveal */
  .cta-1 {
    font-family: 'Cormorant Garamond', serif;
