  }
  .cta-2 span { position: relative; z-index: 1; }
  .cta-2:hover { color: var(--cream); }
  .cta-2:hover::before { transform: none; }

  /* CTA 3 — Gold Glow Pill */
  .cta-3 {
    font-family: 'Jost', sans-serif;
    font-weight: 300;
    font-size: 11px;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: var(--cream);
