  }
  .cta-3:hover { transform: translateY(-2px); box-shadow: 0 20px 40px rgba(42,31,26,0.15); }
  .cta-3:hover::after { opacity: 1; }

  /* CTA 4 — Scroll Arrow */
  .cta-scroll {
    display: flex; flex-direction: column; align-items: center; gap: 10px;
    cursor: none; background: none; border: none; color: var(--dark);
  }
  .cta-scroll-text {
    font-size: 9px; letter-spacing: 0.25em; text-transform: uppercase;
    color: var(--smoke);
    transition: color 0.3s;
  }
  .cta-scroll-arrow {
    width: 1px; height: 50px;
    background: linear-gradient(to bottom, var(--dark), transparent);
    position: relative;
    animation: scrollPulse 2s ease-in-out infinite;
  }
  @keyframes scrollPulse {
    0%, 100% { transform: scaleY(1); opacity: 1; }
    50% { transform: scaleY(0.7); opacity: 0.4; }
  }
  .cta-scroll:hover .cta-scroll-text { color: var(--gold); }

  /* CTA 5 — Magnetic hover word */
  .cta-hover-word {
    font-family: 'Cormorant Garamond', serif;
    font-style: italic;
    font-size: 36px;
    font-weight: 300;
    color: var(--dark);
    background: none; border: none;
    cursor: none;
    position: relative;
    padding: 10px 20px;
    transition: all 0.4s cubic-bezier(.23,1,.32,1);
  }
  .cta-hover-word::before {
