  }

  /* ════════════════════════════════
     SECTION 4 — ALL MENUS COMBINED
  ════════════════════════════════ */
  .menu-styles-grid {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 30px; width: 100%; max-width: 1000px;
