  }
  .menu-b-overlay a:hover { color: var(--gold); letter-spacing: 0.25em; }

  /* Style C — Curtain Drop */
  .menu-c-bg { background: #f2ece4; }
  .menu-c-curtain {
    position: absolute; inset: 0;
    background: var(--blush);
    clip-path: polygon(0 0, 100% 0, 100% 0%, 0 0%);
