    gap: 8px;
  }
  .menu-c-curtain.open {
    clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%);
  }
  .menu-c-curtain a {
    font-family: 'Cormorant Garamond', serif;
    font-style: italic; font-size: 20px;
    color: var(--dark); text-decoration: none; display: block;
    padding: 3px 0;
    transition: color 0.2s;
  }
  .menu-c-curtain a:hover { color: var(--dusty); }

  /* Trigger buttons in cards */
  .trigger-btn {
    background: none; border: 1px solid var(--dark);
    padding: 6px 14px;
    font-family: 'Jost', sans-serif; font-weight: 200;
    font-size: 9px; letter-spacing: 0.15em; text-transform: uppercase;
    color: var(--dark); cursor: none;
    transition: all 0.3s;
  }
  .trigger-btn:hover { background: var(--dark); color: var(--cream); }

  /* ── GOLD LINE DIVIDER ── */
  .gold-line {
    width: 40px; height: 1px;
    background: var(--gold);
    margin: 0 auto 40px;
  }

  /* ── FOOTER NAV ── */
  .section-footer {
    margin-top: 60px;
    text-align: center;
    font-size: 9px; letter-spacing: 0.2em; text-transform: uppercase;
    color: rgba(154,144,144,0.5);
  }

