// ── CURSOR ──
const dot = document.getElementById('cursor-dot');
const ring = document.getElementById('cursor-ring');
let mx = -100, my = -100, rx = -100, ry = -100;

document.addEventListener('mousemove', e => {
  mx = e.clientX; my = e.clientY;
  dot.style.left = mx + 'px';
  dot.style.top = my + 'px';
});

(function animCursor() {
  rx += (mx - rx) * 0.12;
  ry += (my - ry) * 0.12;
  ring.style.left = rx + 'px';
  ring.style.top = ry + 'px';
  requestAnimationFrame(animCursor);
})();

// Hover states
document.querySelectorAll('button, a, [data-cursor]').forEach(el => {
  el.addEventListener('mouseenter', () => {
    if (el.dataset.cursor === 'text') {
      document.body.classList.add('cursor-text');
    } else {
      document.body.classList.add('cursor-hover');
    }
  });
  el.addEventListener('mouseleave', () => {
    document.body.classList.remove('cursor-hover', 'cursor-text');
  });
});

// ── TABS ──
document.querySelectorAll('.tab-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById(btn.dataset.target).classList.add('active');
  });
});

// ── BURGER TOGGLES (section 1) ──
['b1','b2','b3','b4'].forEach(id => {
  const el = document.getElementById(id);
  if (!el) return;
  el.addEventListener('click', () => {
    el.classList.toggle('open');
    if (id === 'b4') {
      document.getElementById('menu-overlay').classList.toggle('open');
    }
  });
});

document.getElementById('overlay-close').addEventListener('click', () => {
  document.getElementById('menu-overlay').classList.remove('open');
  document.getElementById('b4').classList.remove('open');
});

// ── MENU STYLE TOGGLES ──
function toggleMenuA() {
  const t = document.getElementById('ma-trigger');
  const d = document.getElementById('ma-drawer');
  t.classList.toggle('open');
  d.classList.toggle('open');
}
function toggleMenuB() {
  const t = document.getElementById('mb-trigger');
  const o = document.getElementById('mb-overlay');
  t.classList.toggle('open');
  o.classList.toggle('open');
}
function toggleMenuC() {
  const t = document.getElementById('mc-trigger');
  const c = document.getElementById('mc-curtain');
  t.classList.toggle('open');
  c.classList.toggle('open');
}

// Sync card triggers
document.getElementById('ma-trigger').addEventListener('click', toggleMenuA);
document.getElementById('mb-trigger').addEventListener('click', toggleMenuB);
document.getElementById('mc-trigger').addEventListener('click', toggleMenuC);

