  /* Cursor demos (static illustrations) */
  .cd-dot { width: 8px; height: 8px; background: var(--dark); border-radius: 50%; }
  .cd-ring { width: 32px; height: 32px; border: 1px solid var(--dark); border-radius: 50%; position: relative; }
  .cd-ring .cd-dot { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); }
  .cd-cross { width: 20px; height: 20px; position: relative; }
  .cd-cross::before, .cd-cross::after { content: ''; position: absolute; background: var(--dark); }
  .cd-cross::before { width: 1px; height: 100%; left: 50%; top: 0; }
  .cd-cross::after { height: 1px; width: 100%; top: 50%; left: 0; }
  .cd-feather {
