// ── CURSOR ──
const dot = document.getElementById('cursor-dot');
const ring = document.getElementById('cursor-ring');
let mx = -100, my = -100, rx = -100, ry = -100;

document.addEventListener('mousemove', e => {
  mx = e.clientX; my = e.clientY;
  dot.style.left = mx + 'px';
  dot.style.top = my + 'px';
});

(function animCursor() {
  rx += (mx - rx) * 0.12;
  ry += (my - ry) * 0.12;
  ring.style.left = rx + 'px';
  ring.style.top = ry + 'px';
  requestAnimationFrame(animCursor);
})();

// Hover states
document.querySelectorAll('button, a, [data-cursor]').forEach(el => {
  el.addEventListener('mouseenter', () => {
    if (el.dataset.cursor === 'text') {
      document.body.classList.add('cursor-text');
    } else {
      document.body.classList.add('cursor-hover');
    }
  });
  el.addEventListener('mouseleave', () => {
    document.body.classList.remove('cursor-hover', 'cursor-text');
  });
});

// ── TABS ──
document.querySelectorAll('.tab-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById(btn.dataset.target).classList.add('active');
  });
});

// ── BURGER TOGGLES (section 1) ──
['b1','b2','b3','b4'].forEach(id => {
  const el = document.getElementById(id);
  if (!el) return;
  el.addEventListener('click', () => {
    el.classList.toggle('open');
    if (id === 'b4') {
      document.getElementById('menu-overlay').classList.toggle('open');
    }
  });
});

document.getElementById('overlay-close').addEventListener('click', () => {
  document.getElementById('menu-overlay').classList.remove('open');
  document.getElementById('b4').classList.remove('open');
});

// ── MENU STYLE TOGGLES ──
function toggleMenuA() {
  const t = document.getElementById('ma-trigger');
  const d = document.getElementById('ma-drawer');
  t.classList.toggle('open');
  d.classList.toggle('open');
}
function toggleMenuB() {
  const t = document.getElementById('mb-trigger');
  const o = document.getElementById('mb-overlay');
  t.classList.toggle('open');
  o.classList.toggle('open');
}
function toggleMenuC() {
  const t = document.getElementById('mc-trigger');
  const c = document.getElementById('mc-curtain');
  t.classList.toggle('open');
  c.classList.toggle('open');
}

// Sync card triggers
document.getElementById('ma-trigger').addEventListener('click', toggleMenuA);
document.getElementById('mb-trigger').addEventListener('click', toggleMenuB);
document.getElementById('mc-trigger').addEventListener('click', toggleMenuC);

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

components.js:
// cursor
const cd=document.getElementById('cd'),cr=document.getElementById('cr');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px'});
(function t(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(t)})();
document.querySelectorAll('button,a,[class*="pn-"],[class*="sc-card"]').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});
document.addEventListener('mousedown',()=>document.body.classList.add('clk'));
document.addEventListener('mouseup',()=>document.body.classList.remove('clk'));

// tabs
document.querySelectorAll('.tb').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tb').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.sec').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    document.getElementById(b.dataset.t).classList.add('on');
    window.scrollTo({top:0,behavior:'smooth'});
  });
});

components.css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --black:#2D2D2D;
  --off:#525252;
  --white:#F5F5F5;
  --dg:#314A51;
  --mint:#56686A;
  --burg:#6E3B49;
  --mauve:#B5A19E;
  --blush:#D4B9B5;
  --ease:cubic-bezier(.16,1,.3,1);
  --bounce:cubic-bezier(.34,1.56,.64,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--white);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* ── CURSOR ── */
#cd{width:6px;height:6px;background:var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .3s}
#cr{width:26px;height:26px;border:1.5px solid var(--burg);border-radius:50%;position:fixed;top:0;left:0;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:width .4s var(--ease),height .4s var(--ease),border-color .3s,background .3s}
body.hov #cr{width:50px;height:50px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.75);background:rgba(110,59,73,.15)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px 16px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 16px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:16px;right:16px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--black)}
.tb.on::after{transform:scaleX(1)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:86px 0 80px;flex-direction:column;align-items:center;gap:0}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(24px,3vw,38px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:12px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:48px}

/* ════════════════════════════════════════
   SECTION 1 — SCROLL DOWN ELEMENTS
════════════════════════════════════════ */
.scroll-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0;width:100%;max-width:1040px;padding:0 20px}
.sc-card{background:#fff;border:1px solid rgba(181,161,158,.18);padding:48px 20px 28px;display:flex;flex-direction:column;align-items:center;gap:20px;position:relative;overflow:hidden;cursor:none;transition:border-color .35s}
.sc-card:hover{border-color:rgba(110,59,73,.25)}
.sc-card-label{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;line-height:1.6}

/* 1 — Typographic rotating text */
.sc1{display:flex;align-items:center;justify-content:center;width:90px;height:90px;position:relative}
.sc1 svg{position:absolute;inset:0;width:100%;height:100%;animation:rot 18s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.sc1-inner{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;color:var(--burg);z-index:1;animation:rot 18s linear infinite reverse}

/* 2 — Fine line + petal drop */
.sc2{display:flex;flex-direction:column;align-items:center;gap:0}
.sc2-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;letter-spacing:.12em;color:var(--off);opacity:.7}
.sc2-stem{width:1px;height:44px;background:linear-gradient(to bottom,var(--burg),transparent);position:relative}
.sc2-petal{
  width:10px;height:14px;
  background:none;
  border:1px solid var(--burg);
  border-radius:50% 50% 40% 40%;
  position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);
  animation:petalDrop 2.4s ease-in-out infinite;
}
@keyframes petalDrop{
  0%,100%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:1}
  60%{transform:translateX(-50%) translateY(10px) rotate(8deg);opacity:.3}
  61%{transform:translateX(-50%) translateY(0) rotate(0deg);opacity:0}
  62%{opacity:1}
}

/* 3 — Crosshair + word */
.sc3{position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center}
.sc3::before,.sc3::after{content:'';position:absolute;background:rgba(181,161,158,.4)}
.sc3::before{width:1px;height:100%;left:50%;top:0}
.sc3::after{height:1px;width:100%;top:50%;left:0}
.sc3-dot{width:6px;height:6px;background:var(--burg);border-radius:50%;z-index:1;animation:pulseDot 2s ease-in-out infinite}
.sc3-ring{position:absolute;width:30px;height:30px;border:1px solid var(--burg);border-radius:50%;animation:expandRing 2s ease-out infinite}
@keyframes expandRing{0%{transform:scale(.3);opacity:.8}100%{transform:scale(1.4);opacity:0}}
@keyframes pulseDot{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}

/* 4 — Floral dip */
.sc4{display:flex;flex-direction:column;align-items:center;gap:4px}
.sc4-text{font-size:8.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve)}
.sc4-flora{position:relative;width:40px;height:50px}
.sc4-flora svg{width:100%;height:100%;animation:floraFloat 3s ease-in-out infinite}
@keyframes floraFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}

/* 5 — Bracket frame */
.sc5{display:flex;align-items:center;gap:8px}
.sc5-bracket{display:flex;flex-direction:column;justify-content:space-between;height:36px;width:8px}
.sc5-bracket span{display:block;height:1px;background:var(--burg)}
.sc5-bracket span:nth-child(1),.sc5-bracket span:nth-child(3){width:100%}
.sc5-bracket span:nth-child(2){width:1px;margin-left:0;align-self:flex-start;height:100%;background:var(--burg)}
.sc5-r .sc5-bracket{align-items:flex-end}
.sc5-word{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14px;color:var(--dg)}
.sc5 svg{width:16px;height:16px;animation:arrowBob 1.8s ease-in-out infinite}
@keyframes arrowBob{0%,100%{transform:translateY(0)}50%{transform:translateY(5px)}}

/* 6 — Minimal marquee line */
.sc6{overflow:hidden;width:100%;max-width:140px;position:relative}
.sc6-track{display:flex;gap:20px;animation:sc6move 4s linear infinite;white-space:nowrap}
.sc6-track:hover{animation-play-state:paused}
.sc6-item{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:12px;color:var(--mauve);display:flex;align-items:center;gap:8px;flex-shrink:0}
.sc6-item::after{content:'✦';font-style:normal;font-size:8px;color:var(--burg)}
@keyframes sc6move{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.sc6-line{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--burg),transparent);margin-top:8px}

/* 7 — Ink drop */
.sc7{display:flex;flex-direction:column;align-items:center;gap:8px}
.sc7-label{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve)}
.sc7-drop{width:14px;height:20px;background:none;position:relative}
.sc7-drop::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:10px;height:10px;
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  border:1.5px solid var(--burg);
  animation:dropFall 2s ease-in-out infinite;
}
.sc7-stem{width:1px;height:32px;background:linear-gradient(to bottom,var(--burg),transparent)}
@keyframes dropFall{
  0%{transform:translateX(-50%) translateY(0);opacity:1}
  70%{transform:translateX(-50%) translateY(30px);opacity:.2}
  71%{transform:translateX(-50%) translateY(0);opacity:0}
  72%{opacity:1}
}

/* 8 — Rosette spin */
.sc8{width:72px;height:72px;position:relative;display:flex;align-items:center;justify-content:center}
.sc8 svg{width:100%;height:100%;animation:rot 22s linear infinite}
.sc8-ctr{position:absolute;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:9px;color:var(--burg);text-align:center;line-height:1.3;z-index:1}

/* 9 — Feather quill */
.sc9{display:flex;flex-direction:column;align-items:center;gap:6px}
.sc9-q{font-size:24px;color:var(--mauve);animation:quillSway 3s ease-in-out infinite;transform-origin:bottom center;display:block}
@keyframes quillSway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.sc9-line{width:1px;height:30px;background:linear-gradient(to bottom,var(--mauve),transparent)}
.sc9-text{font-size:8px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve)}

/* 10 — Botanical arrow */
.sc10{position:relative;display:flex;flex-direction:column;align-items:center;gap:0}
.sc10 svg{width:56px;height:80px;animation:sc10bob 2.5s ease-in-out infinite}
@keyframes sc10bob{0%,100%{transform:translateY(0)}50%{transform:translateY(7px)}}

/* 11 — Serif word stack */
.sc11{display:flex;flex-direction:column;align-items:center;gap:2px}
.sc11 span{font-family:'Cormorant Garamond',serif;font-size:10px;letter-spacing:.35em;text-transform:uppercase;color:var(--off);opacity:.3;transition:opacity .3s}
.sc11 span:nth-child(2){opacity:.55;font-size:11px}
.sc11 span:nth-child(3){opacity:.85;font-size:12px;color:var(--burg)}
.sc-card:hover .sc11 span{opacity:1}
.sc11-arr{font-size:16px;color:var(--burg);animation:arrowBob 2s ease-in-out infinite;margin-top:4px}

/* 12 — Arch text */
.sc12{display:flex;align-items:flex-end;justify-content:center;height:60px}
.sc12 svg{width:120px;height:60px}

/* ════════════════════════════════════════
   SECTION 2 — PREV / NEXT NAVIGATION
════════════════════════════════════════ */
.pn-stack{display:flex;flex-direction:column;gap:32px;width:100%;max-width:1040px;padding:0 20px}
.pn-section-label{font-size:8px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);display:flex;align-items:center;gap:12px;margin-bottom:4px}
.pn-section-label::before,.pn-section-label::after{content:'';flex:1;height:1px;background:rgba(181,161,158,.25)}

/* Style A — Luxe Full-Width Split */
.pn-a{display:grid;grid-template-columns:1fr auto 1fr;width:100%;border:1px solid rgba(181,161,158,.2)}
.pn-a-side{padding:28px 32px;display:flex;flex-direction:column;gap:6px;cursor:none;position:relative;overflow:hidden;transition:background .4s;background:#fff}
.pn-a-side::before{content:'';position:absolute;inset:0;background:var(--dg);transform:translateX(-101%);transition:transform .55s var(--ease)}
.pn-a-side.right::before{transform:translateX(101%)}
.pn-a-side:hover::before{transform:none}
.pn-a-dir{font-size:7px;letter-spacing:.28em;text-transform:uppercase;color:var(--mauve);position:relative;z-index:1;transition:color .3s}
.pn-a-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--black);position:relative;z-index:1;transition:color .3s;line-height:1.25}
.pn-a-arr{font-size:20px;color:rgba(181,161,158,.4);position:relative;z-index:1;transition:all .4s var(--bounce);align-self:flex-end;margin-top:4px}
.pn-a-side:hover .pn-a-dir,.pn-a-side:hover .pn-a-title,.pn-a-side:hover .pn-a-arr{color:#fff}
.pn-a-side:hover .pn-a-arr{transform:scale(1.3)}
.pn-a-mid{width:1px;background:rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center}
.pn-a-dot{width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* Style B — Typographic Stacked */
.pn-b{display:flex;justify-content:space-between;align-items:stretch;gap:0;width:100%}
.pn-b-side{flex:1;padding:24px 28px;cursor:none;border:1px solid rgba(181,161,158,.18);position:relative;overflow:hidden;transition:border-color .3s;background:#fff}
.pn-b-side.right{text-align:right}
.pn-b-side::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pn-b-side.right::after{transform-origin:right}
.pn-b-side:hover{border-color:rgba(110,59,73,.25)}
.pn-b-side:hover::after{transform:scaleX(1)}
.pn-b-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.pn-b-num{font-family:'Cormorant Garamond',serif;font-size:48px;font-weight:300;color:rgba(181,161,158,.15);line-height:1;position:absolute;top:16px;right:20px;transition:color .3s}
.pn-b-side.left .pn-b-num{right:auto;left:20px}
.pn-b-side:hover .pn-b-num{color:rgba(110,59,73,.12)}
.pn-b-cat{font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--burg);margin-bottom:4px}
.pn-b-title{font-family:'Cormorant Garamond',serif;font-size:20px;color:var(--dg);line-height:1.25;transition:color .3s}
.pn-b-side:hover .pn-b-title{color:var(--burg)}
.pn-b-arrow{font-size:16px;color:var(--mauve);margin-top:10px;display:block;transition:transform .4s var(--bounce),color .3s}
.pn-b-side:hover .pn-b-arrow{color:var(--burg)}
.pn-b-side.left:hover .pn-b-arrow{transform:translateX(-5px)}
.pn-b-side.right:hover .pn-b-arrow{transform:translateX(5px)}

/* Style C — Botanical Card Pair */
.pn-c{display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%}
.pn-c-card{background:var(--dg);padding:32px;cursor:none;position:relative;overflow:hidden;min-height:160px;display:flex;flex-direction:column;justify-content:flex-end}
.pn-c-card.light{background:#fff;border:1px solid rgba(181,161,158,.2)}
.pn-c-card .flora-bg{position:absolute;top:-10px;right:-10px;opacity:.08;pointer-events:none}
.pn-c-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35);margin-bottom:6px;position:relative;z-index:1}
.pn-c-card.light .pn-c-dir{color:var(--mauve)}
.pn-c-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:19px;color:rgba(245,245,245,.85);line-height:1.25;position:relative;z-index:1;transition:color .3s}
.pn-c-card.light .pn-c-title{color:var(--dg)}
.pn-c-arrow{
  position:absolute;top:24px;right:24px;width:36px;height:36px;
  border:1px solid rgba(245,245,245,.15);border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:14px;color:rgba(245,245,245,.4);
  transition:all .4s var(--bounce);z-index:1;
}
.pn-c-card.light .pn-c-arrow{border-color:rgba(181,161,158,.3);color:var(--mauve)}
.pn-c-card:hover .pn-c-arrow{background:var(--burg);border-color:var(--burg);color:#fff;transform:rotate(45deg)}
.pn-c-line{width:0;height:1px;background:linear-gradient(90deg,rgba(245,245,245,.3),transparent);transition:width .6s var(--ease);margin-bottom:8px;position:relative;z-index:1}
.pn-c-card.light .pn-c-line{background:linear-gradient(90deg,var(--mauve),transparent)}
.pn-c-card:hover .pn-c-line{width:60px}

/* Style D — Minimal text only */
.pn-d{display:flex;align-items:center;justify-content:space-between;width:100%;padding:20px 0;border-top:1px solid rgba(181,161,158,.2);border-bottom:1px solid rgba(181,161,158,.2);gap:20px}
.pn-d-item{cursor:none;display:flex;align-items:center;gap:12px;flex:1;padding:8px 0;transition:opacity .3s}
.pn-d-item:hover{opacity:.7}
.pn-d-item.right{flex-direction:row-reverse;text-align:right}
.pn-d-arr{font-size:18px;color:var(--mauve);transition:transform .35s var(--bounce)}
.pn-d-item:hover .pn-d-arr{color:var(--burg)}
.pn-d-item.left:hover .pn-d-arr{transform:translateX(-5px)}
.pn-d-item.right:hover .pn-d-arr{transform:translateX(5px)}
.pn-d-text{}
.pn-d-hint{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}
.pn-d-name{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:17px;color:var(--dg);margin-top:2px}
.pn-d-mid{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:13px;color:var(--mauve);flex-shrink:0}

/* Style E — Mauve bar with floral */
.pn-e{background:var(--mauve);display:grid;grid-template-columns:1fr auto 1fr;width:100%}
.pn-e-side{padding:24px 28px;cursor:none;position:relative;overflow:hidden;transition:background .4s;display:flex;flex-direction:column;gap:4px}
.pn-e-side.right{text-align:right}
.pn-e-side:hover{background:rgba(110,59,73,.2)}
.pn-e-label{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.5)}
.pn-e-title{font-family:'Cormorant Garamond',serif;font-size:17px;color:var(--white);line-height:1.3;transition:color .3s}
.pn-e-side:hover .pn-e-title{color:#fff}
.pn-e-sep{display:flex;align-items:center;justify-content:center;padding:0 16px}
.pn-e-bloom{font-size:20px;opacity:.4;animation:rot 20s linear infinite}

/* Style F — Ghost cards */
.pn-f{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}
.pn-f-card{border:1px solid rgba(181,161,158,.3);padding:24px;cursor:none;background:#fff;position:relative;transition:all .4s var(--ease);display:flex;align-items:center;gap:16px}
.pn-f-card.right{flex-direction:row-reverse;text-align:right}
.pn-f-card:hover{border-color:var(--burg);background:rgba(110,59,73,.02);transform:translateY(-3px)}
.pn-f-icon{width:44px;height:44px;flex-shrink:0;border:1px solid rgba(181,161,158,.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--mauve);transition:all .4s var(--bounce)}
.pn-f-card:hover .pn-f-icon{border-color:var(--burg);color:var(--burg);transform:scale(1.1)}
.pn-f-card.right:hover .pn-f-icon{transform:scale(1.1)}
.pn-f-dir{font-size:7px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:4px}
.pn-f-title{font-family:'Cormorant Garamond',serif;font-size:16px;color:var(--dg);transition:color .3s}
.pn-f-card:hover .pn-f-title{color:var(--burg)}

/* Style G — Burgundy cinematic */
.pn-g{width:100%;background:var(--burg);display:flex}
.pn-g-side{flex:1;padding:28px 32px;cursor:none;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:5px;transition:background .3s}
.pn-g-side:hover{background:rgba(0,0,0,.15)}
.pn-g-side.right{align-items:flex-end;border-left:1px solid rgba(245,245,245,.1)}
.pn-g-dir{font-size:7px;letter-spacing:.3em;text-transform:uppercase;color:rgba(245,245,245,.35)}
.pn-g-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:20px;color:rgba(245,245,245,.9);line-height:1.25;transition:color .3s}
.pn-g-side:hover .pn-g-title{color:#fff}
.pn-g-line{width:0;height:1px;background:rgba(245,245,245,.3);transition:width .6s var(--ease);margin-top:8px}
.pn-g-side:hover .pn-g-line{width:48px}
.pn-g-side.right .pn-g-line{margin-left:auto}

@media(max-width:640px){
  .pn-a,.pn-b,.pn-c,.pn-e,.pn-f,.pn-g{grid-template-columns:1fr}
  .pn-a-mid{display:none}
  .pn-b{flex-direction:column}
  .pn-g{flex-direction:column}
  .pn-d{flex-direction:column;gap:16px}
  .pn-d-mid{display:none}
  .scroll-grid{grid-template-columns:repeat(2,1fr)}
}

