body.hov #cr{width:52px;height:52px;border-color:var(--mint);background:rgba(86,104,106,.06)}
body.hov #cd{background:var(--mint)}
body.clk #cr{transform:translate(-50%,-50%) scale(.7);background:rgba(110,59,73,.12)}

/* tabs */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,245,245,.94);backdrop-filter:blur(16px);border-bottom:1px solid rgba(110,59,73,.1);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:0;padding:12px}
.tb{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(82,82,82,.45);background:none;border:none;padding:7px 14px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb::after{content:'';position:absolute;bottom:2px;left:14px;right:14px;height:1px;background:var(--burg);transform:scaleX(0);transition:transform .4s var(--ease)}
.tb:hover,.tb.on{color:var(--off)}
.tb.on::after{transform:scaleX(1)}

/* sections */
.sec{display:none;min-height:100vh;padding:86px 20px 80px;flex-direction:column;align-items:center}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(22px,3vw,36px);letter-spacing:.06em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:32px;height:1px;background:var(--burg);margin:10px auto 6px}
.ss{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:44px}

/* grid wrapper */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:1px;width:100%;max-width:1080px;background:rgba(181,161,158,.12)}
.cell{background:var(--white);padding:44px 24px 28px;display:flex;flex-direction:column;align-items:center;gap:16px;cursor:none;transition:background .3s}
.cell:hover{background:#faf8f5}
.lbl{font-size:7.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center}

/* ─────────────────────────────────────
   SECTION 1 — HERO ROTATING ELEMENTS
───────────────────────────────────── */

/* A — Brand flower replacing circle-ring.svg */
.hero-flower{position:relative;display:flex;align-items:center;justify-content:center;width:80px;height:80px}
.hf-rot{animation:rotCW 18s linear infinite;position:absolute;inset:0}
.hf-rot-rev{animation:rotCCW 14s linear infinite;position:absolute;inset:0}
@keyframes rotCW{to{transform:rotate(360deg)}}
@keyframes rotCCW{to{transform:rotate(-360deg)}}
.hf-center{position:absolute;width:10px;height:10px;background:var(--burg);border-radius:50%}

/* B — Dash circle replacement */
.dash-rose{width:90px;height:90px;position:relative;display:flex;align-items:center;justify-content:center}
.dash-rose svg{width:100%;height:100%;animation:rotCW 22s linear infinite}
.dash-rose-dot{position:absolute;width:6px;height:6px;background:var(--mauve);border-radius:50%}

/* C — Triple ring (bg-circle-h-line replacement) */
.triple-ring{position:relative;width:90px;height:56px;display:flex;align-items:center;justify-content:center}
.tr-ring{position:absolute;border-radius:50%;border:1px solid var(--mauve);opacity:.35}
.tr-ring:nth-child(1){width:56px;height:56px;animation:ringBreath 4s ease-in-out infinite}
.tr-ring:nth-child(2){width:72px;height:36px;animation:ringBreath 4s ease-in-out infinite .5s}
.tr-ring:nth-child(3){width:88px;height:22px;animation:ringBreath 4s ease-in-out infinite 1s}
@keyframes ringBreath{0%,100%{opacity:.25}50%{opacity:.55}}

/* D — Petal spinner */
.petal-spin{width:80px;height:80px;position:relative;display:flex;align-items:center;justify-content:center}
.ps-inner{animation:rotCW 12s linear infinite}
.ps-dot{position:absolute;width:8px;height:8px;background:var(--burg);border-radius:50%}

/* E — Dotted orbit */
.orbit{width:88px;height:88px;position:relative;display:flex;align-items:center;justify-content:center}
.orbit svg{animation:rotCW 20s linear infinite;position:absolute;inset:0;width:100%;height:100%}
.orbit-center{position:absolute;width:12px;height:12px;border:1.5px solid var(--burg);border-radius:50%}

/* F — Star of petals */
.star-petals{width:80px;height:80px;position:relative;display:flex;align-items:center;justify-content:center}
.star-petals svg{animation:rotCW 25s linear infinite}

/* ─────────────────────────────────────
   SECTION 2 — BUTTERFLIES
───────────────────────────────────── */

/* 2D line art butterfly */
.butterfly-2d{cursor:none;display:flex;align-items:center;justify-content:center}
.butterfly-2d svg{width:100px;height:80px;transition:transform .3s}
.wing-l,.wing-r{transform-origin:center;transition:transform .6s var(--ease)}
.butterfly-2d:hover .wing-l{transform:rotate(-25deg) scaleY(.8)}
.butterfly-2d:hover .wing-r{transform:rotate(25deg) scaleY(.8)}

/* Flying butterfly on scroll/hover */
.butterfly-fly{width:100px;height:80px;position:relative;cursor:none}
.butterfly-fly svg{width:100%;height:100%}
.bfw-l{transform-origin:50% 55%;animation:wingFlap 1.4s ease-in-out infinite alternate}
.bfw-r{transform-origin:50% 55%;animation:wingFlap 1.4s ease-in-out infinite alternate-reverse}
@keyframes wingFlap{from{transform:scaleX(1)}to{transform:scaleX(.15)}}

/* 3D-feel butterfly */
.butterfly-3d{width:120px;height:100px;cursor:none;display:flex;align-items:center;justify-content:center}
.butterfly-3d svg{width:100%;height:100%}
.b3-wing-l{transform-origin:60% 50%;animation:wing3dL 2.2s cubic-bezier(.4,0,.6,1) infinite alternate}
.b3-wing-r{transform-origin:40% 50%;animation:wing3dR 2.2s cubic-bezier(.4,0,.6,1) infinite alternate}
@keyframes wing3dL{from{transform:perspective(300px) rotateY(-5deg) scaleX(1)}to{transform:perspective(300px) rotateY(-60deg) scaleX(.3)}}
@keyframes wing3dR{from{transform:perspective(300px) rotateY(5deg) scaleX(1)}to{transform:perspective(300px) rotateY(60deg) scaleX(.3)}}

/* Hover-only flap */
.butterfly-hover{width:100px;height:80px;cursor:none}
.butterfly-hover svg{width:100%;height:100%}
.bhw-l,.bhw-r{transform-origin:center 55%}
.butterfly-hover:hover .bhw-l{animation:wingFlap .35s ease-in-out infinite alternate}
.butterfly-hover:hover .bhw-r{animation:wingFlap .35s ease-in-out infinite alternate-reverse}

/* Scroll-triggered float */
.butterfly-float{cursor:none;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:4px}
.butterfly-float svg{width:80px;height:64px;animation:floatUp 3s ease-in-out infinite}
@keyframes floatUp{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-12px) rotate(2deg)}}

/* ─────────────────────────────────────
   SECTION 3 — FLORAL LINE ART FILLERS
───────────────────────────────────── */

/* Divider sprig */
.sprig-div{display:flex;align-items:center;gap:12px;width:100%;max-width:400px}
.sprig-line{flex:1;height:1px;background:linear-gradient(90deg,transparent,var(--mauve))}
.sprig-line.r{background:linear-gradient(90deg,var(--mauve),transparent)}

/* Corner flourish */
.corner-fl{position:relative;width:80px;height:80px}

/* Trailing vine */
.vine{width:100%;max-width:300px;overflow:visible}

/* Quote box */
.quote-flora{border:1px solid rgba(181,161,158,.3);padding:28px 24px 20px;position:relative;max-width:320px;text-align:center}
.quote-flora .qf-corner{position:absolute;width:24px;height:24px;opacity:.4}
.quote-flora .qf-corner svg{width:100%;height:100%}
.qf-tl{top:-1px;left:-1px}
.qf-tr{top:-1px;right:-1px;transform:rotate(90deg)}
.qf-bl{bottom:-1px;left:-1px;transform:rotate(-90deg)}
.qf-br{bottom:-1px;right:-1px;transform:rotate(180deg)}
.qf-text{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--dg);line-height:1.5;margin:8px 0}
.qf-attr{font-size:8px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve)}

/* Tag pill with flower */
.flora-tag{display:inline-flex;align-items:center;gap:6px;border:1px solid rgba(110,59,73,.3);padding:5px 14px;border-radius:999px;font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:var(--burg);cursor:none;transition:all .3s}
.flora-tag:hover{background:var(--burg);color:#fff;border-color:var(--burg)}
.flora-tag svg{width:12px;height:12px;transition:transform .5s var(--ease)}
.flora-tag:hover svg{transform:rotate(180deg)}

/* Stat box with floral accent */
.flora-stat{padding:24px 20px;border:1px solid rgba(181,161,158,.2);position:relative;text-align:center;cursor:none;overflow:hidden;transition:border-color .3s;background:#fff}
.flora-stat:hover{border-color:rgba(110,59,73,.3)}
.fs-accent{position:absolute;top:-8px;right:-8px;opacity:.07;pointer-events:none}
.fs-num{font-family:'Cormorant Garamond',serif;font-size:42px;font-weight:300;color:var(--dg);line-height:1}
.fs-label{font-size:8px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);margin-top:4px}

/* Section eyebrow with petals */
.petal-eyebrow{display:flex;align-items:center;gap:10px;font-size:9px;letter-spacing:.25em;text-transform:uppercase;color:var(--burg)}
.pe-bloom{display:flex;gap:3px;align-items:center}
.pe-bloom span{display:inline-block;width:5px;height:8px;border-radius:50%;background:var(--mauve);opacity:.5}
.pe-bloom span:nth-child(2){height:11px;opacity:.8;background:var(--burg)}
.pe-bloom span:nth-child(3){height:7px;opacity:.5}

/* Connector dots & line */
.connector{display:flex;align-items:center;gap:0;width:100%;max-width:360px}
.conn-dot{width:5px;height:5px;border-radius:50%;background:var(--mauve);flex-shrink:0}
.conn-line{flex:1;height:1px;background:linear-gradient(90deg,var(--mauve),rgba(181,161,158,.1))}
.conn-bloom{flex-shrink:0}

/* ─────────────────────────────────────
   SECTION 4 — CONTAINER / BOX STYLES
───────────────────────────────────── */

.box-a{border:1px solid rgba(181,161,158,.25);padding:28px;position:relative;max-width:280px;cursor:none;transition:border-color .4s}
.box-a:hover{border-color:rgba(110,59,73,.35)}
.box-a::before,.box-a::after{content:'';position:absolute;width:16px;height:16px;border-color:var(--burg);border-style:solid;border-width:0;transition:border-width .4s var(--ease)}
.box-a::before{top:-1px;left:-1px;border-top-width:1.5px;border-left-width:1.5px}
.box-a::after{bottom:-1px;right:-1px;border-bottom-width:1.5px;border-right-width:1.5px}
.box-a-inner{position:relative}
.box-a-inner::before,.box-a-inner::after{content:'';position:absolute;width:16px;height:16px;border-color:var(--burg);border-style:solid;border-width:0;transition:border-width .4s var(--ease)}
.box-a-inner::before{top:-29px;right:-29px;border-top-width:1.5px;border-right-width:1.5px}
.box-a-inner::after{bottom:-29px;left:-29px;border-bottom-width:1.5px;border-left-width:1.5px}
.box-a:hover::before,.box-a:hover::after,.box-a:hover .box-a-inner::before,.box-a:hover .box-a-inner::after{border-width:1.5px}

.box-b{position:relative;padding:28px;max-width:280px;cursor:none}
.box-b::before{content:'';position:absolute;inset:0;border:1px solid rgba(181,161,158,.2);transform:rotate(1.5deg);transition:transform .5s var(--ease)}
.box-b::after{content:'';position:absolute;inset:0;border:1px solid rgba(110,59,73,.12);transform:rotate(-1deg);transition:transform .5s var(--ease)}
.box-b:hover::before{transform:rotate(3deg)}
.box-b:hover::after{transform:rotate(-2.5deg)}
.box-b-inner{position:relative;z-index:1}

.box-c{padding:28px;max-width:280px;background:var(--dg);position:relative;overflow:hidden;cursor:none}
.box-c-bloom{position:absolute;bottom:-20px;right:-20px;opacity:.06}
.box-c-content{position:relative;z-index:1;color:var(--white)}

.box-d{padding:28px;max-width:280px;position:relative;cursor:none}
.box-d-frame{position:absolute;inset:0;pointer-events:none}
/* animated dashes */
.box-d-frame rect{fill:none;stroke:var(--mauve);stroke-width:1;stroke-dasharray:6 4;stroke-dashoffset:0;animation:dashAnim 8s linear infinite}
@keyframes dashAnim{to{stroke-dashoffset:-100}}

.box-e{padding:28px;max-width:280px;border:1px solid rgba(181,161,158,.2);position:relative;cursor:none;overflow:hidden;background:#fff;transition:box-shadow .4s}
.box-e::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--burg),var(--mauve),var(--burg));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.box-e:hover::before{transform:scaleX(1)}
.box-e:hover{box-shadow:0 12px 40px rgba(0,0,0,.06)}

/* shared box typography */
.bx-eyebrow{font-size:7.5px;letter-spacing:.25em;text-transform:uppercase;color:var(--mauve);margin-bottom:8px}
.bx-title{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;color:var(--dg);line-height:1.3;margin-bottom:8px}
.bx-body{font-size:12px;color:var(--off);opacity:.7;line-height:1.7}
.bx-white{color:rgba(245,245,245,.8) !important}
.bx-white-t{color:rgba(245,245,245,.9) !important}

/* ── full width demo ── */
.full-demo{width:100%;max-width:1080px}

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --dg:#314A51;--mint:#56686A;--burg:#6E3B49;
  --mauve:#B5A19E;--blush:#D4B9B5;--cream:#F5F0EA;--off:#525252;
  --gold:rgba(181,161,158,.55);
  --ease:cubic-bezier(.16,1,.3,1);
}
html,body{width:100%;min-height:100vh;overflow-x:hidden}
body{background:var(--cream);font-family:'Outfit',sans-serif;color:var(--off);cursor:none}

/* cursor */
#cd{width:5px;height:5px;background:var(--burg);border-radius:50%;position:fixed;z-index:9999;transform:translate(-50%,-50%);pointer-events:none;transition:background .2s}
#cr{width:24px;height:24px;border:1px solid var(--burg);border-radius:50%;position:fixed;z-index:9998;transform:translate(-50%,-50%);pointer-events:none;transition:all .4s var(--ease)}
body.hov #cr{width:44px;height:44px;border-color:var(--mint);background:rgba(86,104,106,.05)}

/* ── TABS ── */
#tabs{position:fixed;top:0;left:0;right:0;z-index:500;background:rgba(245,240,234,.96);backdrop-filter:blur(20px);border-bottom:1px solid rgba(181,161,158,.2);display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:2px;padding:10px 12px}
.tb{font-size:8px;letter-spacing:.18em;text-transform:uppercase;color:rgba(82,82,82,.4);background:none;border:none;padding:6px 12px;cursor:none;position:relative;transition:color .3s;white-space:nowrap}
.tb.on,.tb:hover{color:var(--off)}
.tb.on::after{content:'';position:absolute;bottom:0;left:12px;right:12px;height:1px;background:var(--burg)}

/* ── SECTIONS ── */
.sec{display:none;min-height:100vh;padding:72px 20px 80px;flex-direction:column;align-items:center}
.sec.on{display:flex}
.sh{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(20px,2.5vw,32px);letter-spacing:.08em;color:var(--dg);text-align:center;margin-bottom:4px}
.gl{width:28px;height:1px;background:var(--burg);margin:8px auto 5px}
.ss{font-size:8px;letter-spacing:.22em;text-transform:uppercase;color:var(--mauve);text-align:center;margin-bottom:36px}

/* ── GRID ── */
.g{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:1px;width:100%;max-width:1100px;background:rgba(181,161,158,.15)}
.g.wide{grid-template-columns:repeat(auto-fill,minmax(220px,1fr))}
.c{background:var(--cream);padding:36px 16px 20px;display:flex;flex-direction:column;align-items:center;gap:12px;cursor:none;transition:background .3s}
.c:hover{background:#fff}
.lbl{font-size:7px;letter-spacing:.2em;text-transform:uppercase;color:rgba(181,161,158,.7);text-align:center;line-height:1.5}

/* ── ANIMATIONS ── */
@keyframes rotCW{to{transform:rotate(360deg)}}
@keyframes rotCCW{to{transform:rotate(-360deg)}}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes pulse{0%,100%{opacity:.4;transform:scale(1)}50%{opacity:1;transform:scale(1.08)}}
@keyframes dash{to{stroke-dashoffset:-40}}
@keyframes twinkle{0%,100%{opacity:.2;transform:scale(.7)}40%{opacity:1;transform:scale(1.1)}80%{opacity:.5;transform:scale(.9)}}
@keyframes breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}
@keyframes shimmer{0%{stroke-dashoffset:0}100%{stroke-dashoffset:-80}}
@keyframes moonrise{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-6px) rotate(2deg)}}
@keyframes waveFlow{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}
@keyframes blink{0%,90%,100%{transform:scaleY(1)}95%{transform:scaleY(0.1)}}
@keyframes unfurl{from{stroke-dashoffset:200}to{stroke-dashoffset:0}}
@keyframes petalOpen{0%,100%{transform:rotate(0deg) scaleY(.7)}50%{transform:rotate(5deg) scaleY(1)}}

/* ── SPARKLE system ── */
.spark{animation:twinkle var(--dur,2s) ease-in-out var(--del,0s) infinite}

/* ── BUTTERFLY (realistic 3D) ── */
.bf-body{transform-origin:center}
.bf-wL{transform-origin:100% 50%}
.bf-wR{transform-origin:0% 50%}
.bf-wrap-anim .bf-wL{animation:flapL var(--speed,1.8s) cubic-bezier(.45,0,.55,1) infinite alternate}
.bf-wrap-anim .bf-wR{animation:flapR var(--speed,1.8s) cubic-bezier(.45,0,.55,1) infinite alternate}
.bf-hover-only .bf-wL,.bf-hover-only .bf-wR{transition:transform .5s var(--ease)}
.bf-hover-only:hover .bf-wL{animation:flapL .6s cubic-bezier(.45,0,.55,1) infinite alternate}
.bf-hover-only:hover .bf-wR{animation:flapR .6s cubic-bezier(.45,0,.55,1) infinite alternate}
@keyframes flapL{from{transform:perspective(400px) rotateY(0deg) scaleX(1)}to{transform:perspective(400px) rotateY(-62deg) scaleX(.85)}}
@keyframes flapR{from{transform:perspective(400px) rotateY(0deg) scaleX(1)}to{transform:perspective(400px) rotateY(62deg) scaleX(.85)}}

/* ── MOTH ── */
@keyframes mothFlap{from{transform:perspective(300px) rotateY(0deg)}to{transform:perspective(300px) rotateY(-70deg)}}
@keyframes mothFlapR{from{transform:perspective(300px) rotateY(0deg)}to{transform:perspective(300px) rotateY(70deg)}}

/* ── TEXT FILLERS ── */
.tf-marquee{overflow:hidden;white-space:nowrap;width:100%;max-width:300px}
.tf-inner{display:inline-flex;gap:0;animation:waveFlow 12s linear infinite}
.tf-word{font-size:8px;letter-spacing:.3em;text-transform:uppercase;color:rgba(181,161,158,.5);padding:0 16px}
.tf-word span{color:var(--burg)}

.vertical-text{writing-mode:vertical-rl;text-orientation:mixed;transform:rotate(180deg);font-family:'Cormorant Garamond',serif;font-style:italic;font-size:11px;letter-spacing:.15em;color:rgba(181,161,158,.5);line-height:1}

.arc-text{font-size:7.5px;letter-spacing:.28em;text-transform:uppercase;fill:var(--mauve)}
.arc-text-burg{fill:rgba(110,59,73,.5)}

.micro-label{font-size:7px;letter-spacing:.35em;text-transform:uppercase;color:rgba(181,161,158,.45);display:flex;align-items:center;gap:8px}
.micro-label::before,.micro-label::after{content:'';display:block;width:16px;height:1px;background:rgba(181,161,158,.3)}

/* ── BOHO SHAPES ── */
.boho-arch{transition:transform .4s var(--ease)}
.c:hover .boho-arch{transform:translateY(-3px)}
.c:hover .rot-hover{animation:rotCW 4s linear infinite}
.c:hover .pulse-hover{animation:pulse .8s ease-in-out infinite}
.c:hover .float-hover{animation:float 2s ease-in-out infinite}

