.micro-label::before,.micro-label::after{content:'';display:block;width:16px;height:1px;background:rgba(181,161,158,.3)}

/* ── BOHO SHAPES ── */
.boho-arch{transition:transform .4s var(--ease)}
.c:hover .boho-arch{transform:translateY(-3px)}
.c:hover .rot-hover{animation:rotCW 4s linear infinite}
.c:hover .pulse-hover{animation:pulse .8s ease-in-out infinite}
.c:hover .float-hover{animation:float 2s ease-in-out infinite}
